daily_ws = wb["Daily Numbers"]
v_daily = vals["Daily Numbers"]

inbound = {}
if inbound_ws is not None:
    for r in range(2, inbound_ws.max_row + 1):
        whs = norm_key(inbound_ws.cell(r, 9).value)
        d = norm_date(inbound_ws.cell(r, 17).value)
        qty = to_num(inbound_ws.cell(r, 13).value)
        if whs is None or d is None:
            continue
        inbound[(whs, d)] = inbound.get((whs, d), 0.0) + qty

errors = {}
if errors_ws is not None:
    for r in range(2, errors_ws.max_row + 1):
        whs = norm_key(errors_ws.cell(r, 9).value)
        d = norm_date(errors_ws.cell(r, 17).value)
        code = norm_key(errors_ws.cell(r, 2).value)
        user = norm_key(errors_ws.cell(r, 28).value)
        qty = to_num(errors_ws.cell(r, 13).value)
        if whs is None or d is None or code is None or user is None:
            continue
        if code == "IR" and qty <= 0:
            continue
        errors[(whs, d, code, user)] = errors.get((whs, d, code, user), 0.0) + qty

users = [
    norm_key(daily_ws.cell(3, 7).value),
    norm_key(daily_ws.cell(3, 8).value),
    norm_key(daily_ws.cell(3, 9).value),
    norm_key(daily_ws.cell(3, 10).value),
]

for r in range(3, 25):
    whs = norm_key(v_daily.cell(r, 1).value)
    d = norm_date(v_daily.cell(r, 12).value)

    m = inbound.get((whs, d), 0.0)

    n = o = p = q = rr = 0.0
    for code, acc in (("II", "n"), ("IR", "o"), ("IT", "p"), ("OV", "q"), ("PI", "r")):
        s = 0.0
        for u in users:
            s += errors.get((whs, d, code, u), 0.0)
        if acc == "n":
            n = s
        elif acc == "o":
            o = s
        elif acc == "p":
            p = s
        elif acc == "q":
            q = s
        else:
            rr = s

    result = m - (n + o + p + q + rr)
    if abs(result - round(result, 2)) < 1e-9:
        result = int(round(result))
    else:
        result = round(result, 2)

    daily_ws.cell(r, 17).value = result
    print(r, whs, d, m, n, o, p, q, rr, result)

wb.save(OUT)
